      'Archon 2026-05-27(KST) 대조 기준 신화 레이드는 6,867 표본에서 궤멸자 99.8%, 알드라치 파괴자 0.1%, 추천 전문화+영웅 빌드 6.0%, 100.0k DPS이고, 쐐기 고단 상위 5%는 3,808 표본에서 궤멸자 99.7%, 알드라치 파괴자 0.2%, 추천 전문화+영웅 빌드 24.0%, 쐐기돌 +21, 113.3k DPS입니다.',
