      '혈기 죽음의 기사는 맞고 나서 죽음의 일격으로 버티는 탱커처럼 보이지만, 실제 실력 차이는 맞기 전에 뼈의 보호막, 룬, 룬 마력, 춤추는 룬 무기, 흡혈을 어떤 상태로 준비했는지에서 갈립니다. 12.0.5 기준 레이드 로그는 산레인 사용률이 높고, 쐐기 고단 로그는 죽음의 인도자 사용률이 압도적입니다. 그래서 이 글은 버튼 순서 암기가 아니라 “다음 큰 피해를 어떤 층으로 받을 것인가”를 기준으로 전투 흐름을 설명합니다.',
    sourceNote:
      "스킬명은 KB에 저장된 ko.wowhead.com 툴팁 API와 Blizzard/Wowhead 한국어 명칭을 사용했습니다. 운용 판단은 Blizzard 한국어 12.0.5 노트, Blizzard 영웅 특성 소개, Wowhead 2026-03-28 혈기 운용/2026-04-21 개요, Icy Veins 2026-05-27 확인 기준 혈기 12.0.5 가이드, Archon 2026-05-27(KST) 대조 기준 최근 14일 WCL 기반 레이드·쐐기 고단 집계, Wowhead 공개 Discord 목록의 Acherus/Death's Advance 경로를 교차 확인했습니다. Archon은 신화 레이드 전체 보스 31,640 표본에서 산레인 70.4%, 죽음의 인도자 29.5%, 추천 전문화+영웅 빌드 9.5%, 114.9k DPS를, 쐐기 고단 전체 던전 5,374 표본에서 죽음의 인도자 90.2%, 산레인 9.7%, 추천 전문화+영웅 빌드 32.1%, 쐐기돌 +21, 112.9k DPS를 표시합니다. 가입 후 열람되는 Discord 채널 원문은 직접 인용하지 않고, 공개 경로와 로그/가이드가 같은 방향을 가리키는 항목만 보조 근거로 둡니다.",
