      'Icy Veins는 혈기를 룬과 룬 마력을 사용해 위협과 생존을 동시에 만드는 생성-소비 탱커로 설명하며, 방어적으로 하든 공격적으로 하든 뼈의 보호막 5중첩 이상, 최적 룬/룬 마력 소비, 피의 소용돌이 충전 낭비 방지가 공통이라고 설명합니다.',
