    summary:
      '냉기 죽음의 기사는 얼음 기둥 안에 사신의 징표, 몰살, 도살기 소비, 신드라고사의 숨결 유지, 서리고룡의 격노 회수를 압축하는 근접 딜러입니다. 12.0.5 기준 레이드와 쐐기 모두 죽음의 인도자 채택률이 압도적이므로, 이 가이드는 죽음의 인도자를 기본 축으로 두고 3타겟 이상에서 절멸을 서리낫으로, 냉기의 일격을 빙하 진군으로 바꾸는 판단을 분리합니다.',
    sourceNote:
      '스킬명과 아이콘은 ko.wowhead.com 툴팁 API 기준 한국어 명칭으로 검증했습니다. 운용 판단은 Blizzard 한국어 12.0.5 패치노트, Wowhead 한국어 2026-04-20 냉기 딜사이클, Wowhead 한국어 2026-02-25 냉기 개요, Icy Veins 2026-05-24 개요와 2026-05-19 딜사이클/특성 가이드, Archon 2026-05-27(KST) 확인 기준 최근 14일 WCL 기반 레이드·쐐기 고단 집계, Wowhead 공개 Discord 목록의 Acherus 경로를 교차 확인했습니다. Archon은 신화 레이드 전체 보스 12,376 표본에서 죽음의 인도자 99.5%, 종말의 기수 0.4%, 추천 전문화+영웅 빌드 59.1%, 158.1k DPS를, 쐐기 고단 전체 던전 1,325 표본에서 죽음의 인도자 99.2%, 종말의 기수 0.7%, 추천 전문화+영웅 빌드 31.2%, 쐐기돌 +22, 204.8k DPS를 표시합니다. Acherus는 공개 진입 경로와 저자 활동 근거만 사용하고 대화 원문은 인용하지 않았습니다.',
