    summary:
      '부정 죽음의 기사는 악성 역병 유지, 하급 구울 스택, 부패 충전, 어둠의 변신과 사자의 군대 창을 묶어 피해를 만드는 소환수형 근접 딜러입니다. 12.0.5 기준 Archon 레이드/쐐기 로그는 종말의 기수가 압도적 기본값이고, Wowhead/Icy Veins는 고정 순서가 아니라 질병, 스택, 쿨다운, 금단의 지식 상태에 따라 우선순위가 바뀌는 전문화로 설명합니다.',
