      '쐐기 첫 3초는 탱커 위협과 생존이 딜사이클 일부입니다. 두개골 강타, 달래기, 쇄도의 포효, 나무 껍질을 오프닝과 별도 줄로 생각해야 사고가 줄어듭니다.',
      '호랑이의 분노 직전에는 기력 과잉을 피합니다. 기력이 이미 가득 찬 상태에서 누르면 회복량과 스냅샷 준비 시간을 동시에 잃습니다.',
