          '불꽃형성자가 쐐기에서 경쟁적으로 보일 수 있는 이유도 여기에 있습니다. 고단 쐐기 집계에서는 비늘사령관 55.0%에 비해 불꽃형성자도 44.9%까지 올라오므로, 풀 길이가 짧거나 경로가 복잡하면 비늘사령관의 깊은 숨결/폭격 가치가 줄어들고 화염 타이밍을 더 안정적으로 굴리는 선택이 나을 수 있습니다. 넓은 +7 이상 표본에서는 비늘사령관 68.5%가 유지되어, 저단부터 중단까지는 비늘사령관 기본값이 여전히 강합니다.',
