      '시간 변칙은 체력이 이미 빠진 뒤 누르는 회복 버튼이 아닙니다. 피해가 오기 전에 메아리 기반과 흡수를 깔고, 피해 후 복구는 되돌리기나 신록의 품으로 따로 처리합니다.',
