      '정지장은 강한 주문을 아무거나 저장하는 창고가 아닙니다. 저장 순서가 방출 순서이므로, 피해 타이머와 맞지 않는 저장은 오히려 다음 복구 창을 망칩니다.',
      '시간 팽창은 탱커나 위험 대상이 맞고 난 뒤가 아니라 맞기 전에 배정합니다. 보존의 강점은 피해를 되돌리는 것만큼 피해가 터지기 전 준비하는 데 있습니다.',
