    sourceStatus:
      'Blizzard 공식 12.0.5 노트, Wowhead 한국어 가이드/툴팁, Icy Veins, Archon/WCL 로그 집계, Trueshot Lodge 공개 서버 경로를 수동 대조했습니다. Archon은 신화 레이드 58,728 표본, 고단 쐐기 12,529 표본, +7 이상 쐐기 244,005 표본 기준으로 확인했습니다.',
    summary:
      '야수 사냥꾼은 쉬운 전문화처럼 보이지만, 실제 성능은 야수의 격노 창을 얼마나 자주 열고 그 안에 살상 명령, 날카로운 사격, 자연의 동맹 조건, 광역 야수의 회전베기 상태를 얼마나 촘촘하게 넣는지에 달려 있습니다. 12.0.5 기준 레이드는 무리의 지도자가 압도적인 기본값이고, 쐐기는 무리의 지도자와 어둠 순찰자가 함께 보이므로 레이드 기본 운용과 쐐기 분기 운용을 분리해 읽어야 합니다.',
