      'Blizzard 공식 노트, Wowhead 한국어 가이드/툴팁, Icy Veins 12.0.5 가이드, Archon/WCL 로그 집계, Trueshot Lodge 공개 서버 경로를 수동 대조했습니다. Archon은 신화 레이드 16,640 표본, 고단 쐐기 1,356 표본, +7 이상 쐐기 25,755 표본 기준으로 확인했습니다.',
    summary:
      '사격 사냥꾼은 조준 사격을 중심으로 전투를 설계하는 시전형 원거리 딜러입니다. 12.0.5 기준 핵심은 조준 사격과 속사를 많이 쓰는 것만이 아니라, 그 뒤에 생기는 정밀 사격을 다음 큰 시전 전에 소비하고, 광역에서는 교묘한 사격이 켜진 상태로 조준 사격과 속사를 넣는 것입니다. 레이드는 파수꾼 비중이 높고 쐐기는 어둠 순찰자가 우세하므로, 같은 조준 사격 중심 구조 위에 서로 다른 보조 판단을 얹어 읽어야 합니다.',
    sourceNote:
      '스킬명은 KB와 ko.wowhead.com 툴팁 기준 한국어 명칭을 사용했습니다. 운용 판단은 Blizzard 한국어 12.0.5 공식 노트, Wowhead 2026-05-01 사격 특성/딜사이클, Icy Veins 12.0.5 사격 딜사이클/특성 가이드, Archon 2026-05-27(KST) 확인 기준 레이드 파수꾼 70.4% / 어둠 순찰자 29.5%, 고단 쐐기 어둠 순찰자 93.9% / 파수꾼 6.0%, +7 이상 쐐기 어둠 순찰자 85.7% / 파수꾼 14.2%, Trueshot Lodge 공개 서버 경로를 교차 확인했습니다. Discord 내부 채널 원문은 직접 인용하지 않고 공개 경로 확인과 로그/가이드가 일치하는 결론만 보조 근거로 씁니다.',
