    summary:
      '악마 흑마법사는 영혼의 조각을 피해 주문으로 바로 바꾸는 전문화가 아니라, 조각을 소환수와 폭군 창의 입력값으로 바꾼 뒤 악마 폭군 소환 동안 굴단의 손을 얼마나 압축하는지로 결과가 갈리는 전문화입니다. 12.0.5 실전 표본은 Diabolist가 레이드와 쐐기 모두에서 우세하므로, 이 가이드는 악마 폭군 소환을 그래프 중심에 두고 굴단의 손, 공포사냥개 부르기, 악마의 핵, 흑마법서: 임프 군주, 흑마법서: 지옥 유린자, 파멸수호병 소환, 파열의 관계를 읽는 방식으로 구성합니다.',
    sourceNote:
      'Icy Veins는 2026-05-23 기준 악마 흑마법사를 임시 악마 소환과 조각 생성/소비 전문화로 설명하고, 2026-05-19 딜사이클 문서에서는 악마 폭군 소환의 피해 계산이 활성 소환수에 따라 동적으로 갱신되기 때문에 폭군 전 준비만큼 폭군 중 굴단의 손 압축이 중요하다고 정리합니다. Wowhead 한국어 딜사이클 문서는 마력 착취, 공포사냥개 부르기, 굴단의 손, 흑마법서 계열, 악마 폭군 소환, 파멸수호병 소환, 악마 화살, 파열의 우선순위를 제시합니다. Archon 2026-05-25(KST) 확인 기준 최근 14일 표본은 신화 레이드 상위 50% 74,507파싱에서 Diabolist 90.3%, Soul Harvester 9.6%, 쐐기 +7 이상 전체 던전 289,823파싱에서 Diabolist 99.4%, Soul Harvester 0.5%, 고단 쐐기 상위 5% 14,815파싱에서 Diabolist 99.9%, Soul Harvester 0.0%를 보여줍니다.',
