      '흑마법서: 임프 군주와 흑마법서: 지옥 유린자는 선택 노드 성격이 강하므로, 차트에서는 같은 큰 악마 창으로 묶되 유틸리티 목적은 본문에서 분리합니다.',
      'Soul Harvester는 레이드 일부 표본에서만 보조 분기로 취급합니다. 쐐기 기본 설명은 Diabolist 기준으로 읽습니다.',
      'Discord 자료는 공개 진입 경로와 저자 소개만 근거화하고, 비공개 채널 대화나 날짜가 불명확한 요약은 직접 근거로 쓰지 않습니다.',
