      '악마의 핵이 2중첩에 가까우면 악마 화살로 조각을 회복합니다. 단, 폭군 직전에는 악마 화살을 아무렇게나 털지 말고 굴단의 손으로 이어질 조각 계획을 같이 봅니다.',
      '파열은 광역에서 야생 임프를 피해로 바꾸는 버튼입니다. 6마리 기준을 맞추지 못했거나 곧 폭군 창이 필요하면 총량보다 다음 창 재료 보존이 우선일 수 있습니다.',
      '악마의 의식/황폐 축이 기본값인 표본에서는 흑마법서 계열과 파멸수호병 소환을 폭군 창과 같이 봅니다. 영혼 수확자 축은 악마의 핵과 악마 화살 보조 분기로 따로 읽습니다.',
