          '파괴 로그를 볼 때는 피해량 순위부터 보면 원인을 놓치기 쉽습니다. 먼저 제물 또는 쇠퇴 유지율과 공백 위치를 보고, 다음으로 5조각 과충전 시간을 확인합니다. 그 다음 점화 2충전 방치, 역류 소비 대상, 대혼란 창 안의 혼돈의 화살, 지옥불정령 소환 중 소비 밀도를 순서대로 봅니다.',
          '광역 로그는 불의 비 피해만 높다고 좋은 로그가 아닙니다. 불의 비가 깔린 시간에 대상이 실제로 살아 있었는지, 대혼란이 가능한 2타깃 창을 불의 비로 덮어 버리지는 않았는지, Hellcaller의 적개심이 쇠퇴 대상 수와 맞았는지, Diabolist의 황폐가 우선 대상 창에 들어갔는지를 분리해서 봐야 합니다.',
          '마지막으로 생존과 이동을 봅니다. 죽거나 긴 시전이 끊긴 구간은 단순 개인 실수가 아니라 악마의 마법진, 악마의 관문, 영원한 결의, 어둠의 서약 계획이 부족했다는 뜻일 수 있습니다. 파괴는 이동이 길어질수록 조각 생성과 소비가 모두 늦어지므로, 생존 로그가 딜 로그와 직접 연결됩니다.',
