    sourceStatus: 'Blizzard 12.0.5, Wowhead, Icy Veins, Archon 신화 레이드/쐐기 로그, Peak of Serenity 공개 가이드와 PeakOfSerenity Discord 경로 확인.',
    graphCenterSkillId: '115069',
    summary:
      '양조 수도사는 체력바가 흔들린 뒤에 반응하는 탱커가 아니라, 시간차에 저장된 미래 피해를 읽고 정화주와 천신주를 어느 순간에 나눌지 결정하는 탱커입니다. 12.0.5 기준 핵심은 맥주통 휘두르기와 후려차기로 회전 엔진을 끊기지 않게 유지하면서, 위험한 시간차에는 정화주, 다음 큰 타격에는 천신주, 긴 압박 구간에는 흑우 니우짜오의 원령과 강화주 계열을 겹쳐 배치하는 것입니다. 영웅 특성은 로그에서 음영파 비중이 높지만, 조화의 형은 천신주/천신의 주입과 위치 에너지 방출을 통해 방어 판단을 더 촘촘하게 만드는 분기입니다.',
    sourceNote:
      'Icy Veins 양조 가이드와 딜사이클 페이지는 2026-05-19에 12.0.5 기준으로 갱신되었고, Wowhead 양조 딜사이클은 2026-04-19 기준으로 시간차, 교묘한 투사, 정화주, 천신주/천신의 주입, 맥주통 휘두르기, 후려차기, 흑우 니우짜오의 원령, 폭발하는 맥주통을 핵심 축으로 설명합니다. Wowhead 특성 빌드 페이지는 2026-05-20 기준 레이드와 쐐기 빌드를 분리해 제공합니다. Archon은 2026-05-27(KST) 확인 시점에 신화 레이드 all bosses 최근 14일 33,907파싱에서 음영파 81.7%, 조화의 형 18.2%를, 쐐기 +7~+23 전체 던전 최근 14일 239,438파싱에서 음영파 57.1%, 조화의 형 42.8%를 표시했습니다. Peak of Serenity는 12.0.5 공개 가이드와 PeakOfSerenity Discord 진입 경로를 제공하고, 쐐기에서 조화의 형과 음영파를 대상 수와 우선 대상 요구에 맞춰 선택할 수 있다고 설명하므로 직업 커뮤니티 보조 근거로 사용했습니다.',
