          '후려차기는 기 과충전 방지, 같은 기술 반복 방지, 수도원의 가르침 발동 관리가 겹친다.',
          '두 버튼의 평가는 총횟수가 아니라 전후 기술과 자원 상태를 함께 봐야 한다.',
