      '보호 성기사는 체력바가 내려간 뒤 반응하는 탱커가 아니라, 신성화 안에서 신성한 힘을 만들고 큰 물리 피해 전에 정의의 방패 공백을 줄이는 탱커입니다. 12.0.5 핫픽스는 기본 방어도와 헌신적인 수호자 계열 내구도를 올렸지만, 운용의 중심은 여전히 정의의 방패입니다. 이 페이지는 정의의 방패를 그래프 중심 노드로 두고 신성화 위치, 응징의 방패와 심판 생성, 영광의 서약 복구, 천상의 종 광역 창, 레이드 기사단 창, 쐐기 빛대장장이 지원 창을 하나의 방어 시간표로 읽게 합니다.',
    sourceNote:
      'Blizzard 핫픽스는 2026-05-05 보호 성기사 기본 방어도 10% 증가와 2026-05-19 내구도 보강을 명시했습니다. 특히 황혼의 축복 피해 감소, 신성화된 판금 체력 보정, 헌신적인 수호자 지속시간과 피해 감소량, 파수꾼 지속시간이 조정되어 방어기 창이 실제로 길어졌습니다. Wowhead는 정의의 방패를 신성한 힘 3~5 또는 무료일 때 쓰며 과충전을 피하라고 정리하고, 오프닝 목표를 정의의 방패 활성화와 응징의 격노/천상의 종 전개로 설명합니다. Icy Veins는 헌신적인 수호자를 자주 쓰되 고대 왕의 수호자는 큰 피해 전에 계획하라고 설명합니다. Archon은 2026-05-27(KST) 확인 시 신화 레이드 all bosses 최근 14일 8,875파싱에서 기사단 87.9%, 빛대장장이 12.0%, 추천 Spec & Hero 13.3%, 69.4k DPS를, 쐐기 +7~+23 전체 던전 최근 14일 135,641파싱에서 빛대장장이 80.2%, 기사단 19.7%, 추천 Spec & Hero 19.6%, 쐐기돌 +22, 89.2k DPS를 표시했습니다. 따라서 본문은 레이드와 쐐기의 영웅 특성 판단을 분리합니다.',
