          '12.0.5 핫픽스 이후 보호 성기사는 이전보다 기본 내구도가 좋아졌지만, 이 변화가 방어 공백을 지워 주지는 않습니다. 신성화 밖에서 맞거나, 신성한 힘을 과충전하거나, 정의의 방패가 비는 순간에 큰 평타를 맞거나, 헌신적인 수호자와 고대 왕의 수호자를 같은 구간에 겹치면 로그의 피해 패턴은 여전히 거칠어집니다. 좋은 보호 성기사 로그는 높은 피해량보다 큰 피해 직전 방어 시간이 비어 있지 않은 흔적을 먼저 보여 줍니다.',
