    sourceStatus:
      'Blizzard 12.0.5/핫픽스, Wowhead, Icy Veins, Archon/WCL 로그 집계, Hammer of Wrath 공개 Discord 경로 확인.',
    summary:
      '징벌 성기사는 단순히 신성한 힘을 만들고 비우는 전문화가 아니라, 사형 선고 안에 응징의 격노, 파멸의 재, 빛의 망치, 최후의 선고를 얼마나 정확히 압축하는지로 손실이 갈리는 근접 딜러입니다. 평상시에는 심판의 칼날, 심판, 성전사의 일격, 천벌의 망치가 신성한 힘의 빈칸을 만들고, 단일은 최후의 선고 또는 기사단의 선고, 광역은 천상의 폭풍으로 결산합니다. 2026-05-25 기준 공개 로그 집계에서는 기사단이 레이드와 쐐기 모두 압도적으로 우세하므로, 이 문서는 사형 선고-빛의 망치 창을 중심으로 설명하되 태양의 사자 전환점도 별도 보류로 남깁니다.',
    sourceNote:
      'Wowhead는 징벌의 기본 구조를 심판의 칼날과 심판으로 신성한 힘을 만들고 최후의 선고 또는 천상의 폭풍으로 소비하는 우선순위형 딜사이클로 설명합니다. Icy Veins는 2026-05-19 기준으로 신성한 힘과 시간 관리, 성전사의 일격 대체 선택지, 전쟁의 기술 발동 대응을 강조합니다. Archon은 2026-05-25(KST) 확인 시 최근 14일 WCL 기반 신화 레이드 63,473파싱에서 기사단 99.8%, 쐐기 +7~+23 전체 던전 354,535파싱에서 기사단 99.6% 사용률을 표시했습니다. Hammer of Wrath는 공개 Discord 경로와 서버 설명만 검증 근거로 사용하고, 비공개 채널 원문은 인용하지 않습니다.',
