          '쐐기: 큰 풀은 천상의 폭풍, 위험 대상은 사형 선고와 최후의 선고로 다시 모읍니다.',
          '근접 유지가 어려운 전투에서는 이동 보조와 유틸리티가 실제 피해 유지율을 바꿉니다.',
          '기사단 기본값은 유지하되, 전투 형태가 바뀌면 소모기와 유틸리티 판단도 같이 바꿉니다.',
