    graphCenterSkillId: '20473',
    sourceStatus:
      'Blizzard 12.0.5/핫픽스, Wowhead, Icy Veins, Archon/WCL 2026-05-27 로그 집계, Hammer of Wrath 공개 Discord 경로 확인.',
    summary:
      '신성 성기사는 피가 빠진 뒤 가장 큰 주문을 찾는 힐러가 아니라, 신성 충격으로 신성한 힘과 빛 주입을 만들고, 빛의 봉화와 구세주의 봉화 대상망으로 치유를 분배하며, 영광의 서약·영원의 불꽃·여명의 빛을 피해 유형에 맞춰 비우는 힐러입니다. 이 페이지는 신성 충격을 중심 노드로 두고, 봉화 대상망, 신성한 힘 소비, 오라 숙련과 응징의 격노, 티르의 해방, 태양의 사자 새벽빛 창, 빛대장장이 신성한 무장 분기를 하나의 회복 시간표로 읽게 합니다.',
    sourceNote:
      'Blizzard 12.0.5 노트는 신성 충격, 영광의 서약, 영원의 불꽃, 여명의 빛, 상급 심판, 구세주의 봉화, 빛대장장이 신성한 무장 조정을 명시했고, 2026-05-05 핫픽스는 영광의 서약·영원의 불꽃·여명의 빛을 추가로 올렸습니다. Wowhead는 신성 성기사를 봉화와 신성한 힘을 쓰는 판금 힐러로 설명하고, Icy Veins는 빛 주입을 상황에 따라 빛의 섬광 또는 심판으로 소비하라고 정리합니다. Archon은 2026-05-27(KST) 확인 시 최근 14일 WCL 기반 신화 레이드 29,625파싱에서 태양의 사자 99.7%, 빛대장장이 0.2%, 추천 전문화+영웅 빌드 65.9%, 174.9k HPS/6.7k DPS를 표시했습니다. 쐐기 +7~+23 전체 던전은 109,686파싱에서 태양의 사자 89.2%, 빛대장장이 10.7%, 추천 전문화+영웅 빌드 27.0%, +21/75.2k HPS/21.5k DPS였습니다. 본문은 태양의 사자를 기본 축으로 설명하되 빛대장장이는 쐐기와 응징의 성전사 분기로 유지합니다.',
