    sourceStatus:
      'Blizzard 12.0.5/핫픽스, Wowhead, Icy Veins, Archon/WCL 2026-05-27 로그 집계, Skyhold 공개 Discord 경로 확인.',
    summary:
      '방어 전사는 큰 피해가 온 뒤 생존기를 누르는 탱커가 아니라, 방패 올리기의 유효 유지율로 물리 피해를 평탄화하고, 방패 밀쳐내기와 천둥벼락으로 분노를 만들며, 고통 감내와 주요 생존기를 다음 피해 전에 배치하는 능동 방어 탱커입니다. 이 페이지는 방패 올리기를 중심 노드로 두고, 방패 밀쳐내기 분노 엔진, 고통 감내 흡수층, 산왕 천둥벼락 루프, 거신 쇄파 분기, 주문 반사와 사기의 외침 생존기 판단을 하나의 탱킹 시간표로 읽게 합니다.',
    sourceNote:
      'Blizzard 2026-05-12 핫픽스는 방어 전사가 강한 근접 완화에 비해 마법 피해와 지속 피해 대응이 뒤처진다고 설명하며, 불길을 지나, 결사단원, 고통 감내를 상향했습니다. Icy Veins는 방패 올리기를 기본 능동 방어로 두고 실제로 맞는 동안의 유효 유지율을 강조하며, 고통 감내는 방패 올리기 대체물이 아니라 추가 흡수층이라고 정리합니다. Wowhead 딜사이클은 방패 밀쳐내기 발동을 즉시 쓰고, 천둥벼락으로 분쇄를 적용하며, 과잉 분노를 고통 감내에 쓰는 구조를 제시합니다. Archon은 2026-05-27 확인 시 최근 14일 신화 레이드 19,709 표본에서 산왕 98.6%, 쐐기 7단 이상 91,133 표본에서 산왕 97.1% 선택률을 보여 주므로, 본문은 산왕을 기본 축으로 설명하되 거신은 광역 피해/쇄파 분기로 보존합니다. Icy Veins 방어 전사 문서는 Skyhold 전사 Discord 이론공식/운영진인 Mwahi 작성 문서로 확인되어, 공개 Discord 경로와 같은 방향의 보조 근거로만 사용합니다.',
