    summary:
      '잠행 도적은 단순히 어둠의 춤을 자주 누르는 전문화가 아니라, 은밀한 기술을 기준점으로 어둠의 춤, 어둠의 칼날, 그림자 일격, 절개, 고대의 기술, Trickster의 무형검/최후의 일격을 짧은 피해 창 안에 압축하는 90초 극딜형 근접 딜러입니다. 평상시에는 기력과 연계 점수에 묶여 느리게 움직이고, 창이 열리면 그림자 일격으로 빠르게 연계 점수를 만들며 은밀한 기술과 절개로 소비합니다. 쐐기에서는 2대상 이상부터 표창 폭풍과 검은 화약이 들어오지만, Deathstalker의 어둡고 어두운 밤이나 고대의 기술이 절개 가치를 다시 끌어올릴 수 있어 광역이라고 무조건 검은 화약만 누르는 구조도 아닙니다.',
    sourceNote:
      'Blizzard 12.0.5 노트는 잠행 Deathstalker의 죽음추적자의 징표, 죽음의 표시, Trickster 구름 덮개 변경을 명시하고, 2026-05-05 핫픽스는 잠행 전체 피해 7% 증가와 Trickster 구름 덮개/비양심적 수법 조정을 명시합니다. Wowhead 잠행 딜사이클은 2026-05 중순 갱신본에서 모든 쿨기를 은밀한 기술에 정렬하고, Icy Veins는 2026-05-23 갱신 기록에서 12.0.5 및 5월 튜닝 반영을 확인했습니다. Archon은 2026-05-25 열람 시 Mythic Raid All Bosses 26,761 parses에서 Trickster 99.8%, Deathstalker 0.1%, 추천 Spec & Hero 41.0%, Mythic+ +7~+23 All Dungeons 72,334 parses에서 Trickster 99.7%, Deathstalker 0.2%, 추천 Spec & Hero 38.8%를 보여줍니다. Ravenholdt는 Wowhead 공식 Discord 목록과 Icy Veins 저자 소개에서 확인했으며, 비공개 채널 원문은 직접 인용하지 않고 공개 진입 경로와 로그/가이드 교차 검증 근거로만 사용합니다.',
