          '그래서 이 가이드의 관계 그래프 중앙은 어둠의 춤이 아니라 은밀한 기술입니다. 어둠의 춤은 은밀한 기술을 넣는 창, 어둠의 칼날은 90초 큰 창, 그림자 일격은 그 창을 채우는 생성기, 절개는 은밀한 기술 이후와 빈 소비 구간을 메우는 마무리 일격입니다. 고대의 기술은 그림자 기술 중첩을 통해 다음 마무리 일격과 복제된 그림자를 연결합니다.',
