          '잠행 오프닝은 스킬 나열로 외우면 쉽게 무너집니다. 전투 시작 전 은신과 독 적용을 확인하고, 난도질이 필요한 상황에서는 전투 초반 유지 상태를 정리합니다. 이후 어둠의 칼날과 어둠의 춤을 맞추고, 그림자 일격으로 연계 점수를 만들며 은밀한 기술을 첫 강한 마무리 일격으로 넣습니다. 소멸은 낮은 연계 점수에서 새 은신 창을 얻는 공격 자원으로 사용합니다.',
