          '그래서 쐐기 보조 차트는 공격 흐름 옆에 유틸리티 매트릭스를 붙이는 편이 좋습니다. 풀 시작 전 혼절시키기/속임수 거래, 위험 시전 중 발차기/실명, 광역 피해 전 교란, 마법 디버프 전 그림자 망토, 물리 정면 공격 전 회피를 시간축에 나눠 배치하면 실제 플레이에서 읽기 쉽습니다.',
