          '핵심 체크: 교란, 그림자 망토, 회피를 아껴서 죽는 것이 가장 큰 딜 손실입니다.',
          '발차기와 실명은 우선순위 대상 피해보다 먼저 필요한 순간이 있습니다.',
          '속임수 거래와 혼절시키기는 전투 전 설계 단계에서 이미 딜사이클에 영향을 줍니다.',
