    summary:
      '고양 주술사는 근접 타격으로 소용돌이치는 무기 중첩을 만들고, 그 중첩을 번개 화살, 연쇄 번개, 폭풍 같은 주문으로 전환하는 근접 배틀메이지입니다. 겉으로는 폭풍의 일격, 용암 채찍, 낙뢰, 야수 정령, 파멸의 바람, 세계의 분리 같은 버튼이 많은 전문화처럼 보이지만, 실제 판단의 중심은 소용돌이치는 무기를 언제 비우고 언제 조금 더 굴릴지입니다. 12.0.5 기준 토템술사는 쇄도하는 토템, 뜨거운 손, 용암 채찍, 파멸의 바람을 1분 창으로 묶고, 폭풍인도자는 폭풍, 초자력 충전, 낙뢰, 승천을 2분 또는 큰 풀 타이머에 맞춥니다.',
    sourceNote:
      'Wowhead 고양 개요는 2026-05-09, 딜사이클은 2026-05-19, 특성 문서는 2026-05-11에 갱신되었습니다. Icy Veins 딜사이클과 특성 문서는 2026-05-19에 12.0.5 기준으로 갱신되었습니다. Blizzard 12.0.5 노트는 넘치는 소용돌이 보조 효과와 분노의 소용돌이/넘치는 소용돌이 명칭 교체를 확인해 주고, 2026-05-05 핫픽스는 고양 전체 피해 보정과 폭풍인도자 자연 피해 보정을 따로 확인해 줍니다. Archon은 2026-05-26 확인 시점에 신화 레이드 전체 보스 상위 50% 최근 14일 8,757표본에서 토템술사 65.9%, 폭풍인도자 34.0%, 추천 전문화+영웅 빌드 30.6%, 166.5k DPS를 보여 주고, 쐐기 고단 전체 던전 상위 5% 최근 14일 3,808표본에서는 폭풍인도자 88.6%, 토템술사 11.3%, 추천 전문화+영웅 빌드 44.5%, 쐐기돌 +22, 193.4k DPS를 보여 줍니다. 그래서 이 가이드는 레이드 기본값을 토템술사로 두되, 조직된 고단 쐐기와 5~6타깃 큰 풀은 폭풍인도자를 별도 축으로 분리합니다.',
