    tips: [
      '오프닝은 “화염 충격 확인 → 폭풍수호자 → 용암 폭발 → 승천 → 선조의 신속함 → 강화 번개 화살”의 손실 방지 흐름으로 읽습니다. 실제 전투에서는 대상 생성과 이동 패턴 때문에 전역 하나가 앞뒤로 움직일 수 있습니다.',
      '폭풍수호자를 누르기 전 화염 충격 남은 시간, 용암 폭발 충전, 소용돌이 공간을 먼저 확인합니다. 이 셋 중 하나가 망가진 상태로 큰 창에 들어가면 강화 주문만 세고 전체 창은 약해집니다.',
      '폭풍인도자에서는 폭풍 발동을 보자마자 아무 때나 누르기보다 폭풍수호자, 승천, 대상 수와 겹치는지 판단합니다.',
      '정기 작렬을 쓰는 빌드는 대지 충격 자리에 정기 작렬을 끼워 넣을 수 있지만, 소용돌이 과충전과 다음 폭풍수호자 창을 방해하면 손실입니다.',
      '광역에서 지진은 몹이 실제로 서 있을 때만 가치가 있습니다. 탱커 이동 경로가 흔들리면 강화 연쇄 번개 이후 소비 타이밍을 늦춥니다.',
      '이동이 예고되어 있으면 영혼나그네의 은총을 폭풍수호자/승천 창에 배정하고, 선조의 신속함 같은 즉시시전 자원을 무의미한 채우기 주문에 쓰지 않습니다.',
      '쐐기에서는 날카로운 바람, 축전 토템, 정화가 강화 주문보다 우선되는 순간이 있습니다. 위험 주문을 놓친 폭풍수호자 창은 좋은 오프닝이 아닙니다.',
      '로그 검수는 총 DPS보다 화염 충격 공백, 용암 폭발 충전 낭비, 소용돌이 과충전, 폭풍수호자 강화 주문 소비, 이동 중 빈 전역 순서로 봅니다.',
    ],
