    summary:
      '수양 사제는 피가 빠진 뒤 따라가는 힐러가 아니라, 피해가 오기 전에 속죄와 보호막을 깔아 두고 피해가 들어오는 순간 회개, 정신 분열, 어둠의 권능: 죽음으로 되돌려 받는 힐러입니다. 12.0.5 기준 핵심은 사도와 신의 권능: 광휘로 약 8초 안에 램프를 압축하고, 공허의 보호막과 신의 권능: 보호막으로 죽을 대상을 먼저 살리며, 궁극의 참회와 신의 권능: 방벽을 같은 피해에 겹치지 않게 나누는 것입니다. 과거 운용 버튼이나 현재 기본 흐름과 무관한 유사명 특성은 전투 흐름 차트에 넣지 않습니다.',
    sourceNote:
      'Blizzard 12.0.5 노트는 수양의 속죄 전환을 28%로 낮추는 대신 신의 권능: 보호막, 공허의 보호막, 신의 권능: 광휘, 간청, 순간 치유, 어둠의 치유를 25% 보강했습니다. Wowhead 운용 가이드는 사도 이후 신의 권능: 광휘가 즉시 시전으로 바뀌면서 약 8초 안에 속죄 램프를 압축하고, 공허의 보호막을 사용 가능할 때 우선 처리하며, 레이드에서는 신의 권능: 보호막/간청/순간 치유/사도/광휘로 20명 속죄를 만드는 흐름을 설명합니다. Icy Veins 2026-05-19 운용 문서는 공허의 보호막이 현재 출력의 큰 비중을 차지하고, 회개 3회 안에 한 번 보장되는 덱형 발동 구조라 회개와 공허의 보호막을 피해 타이머에 맞춰 관리해야 한다고 설명합니다. Wowhead 특성 문서는 레이드와 쐐기 추천을 예언자 중심으로 두며, 예언자가 던전에서 단일 대상 복구와 트리아지에 더 강하고 공허술사는 피해 기여가 높은 분기라고 설명합니다. Archon은 2026-05-27(KST) 확인 기준 신화 레이드 최근 14일 상위 50% 31,844표본에서 예언자 99.9%, 추천 전문화+영웅 빌드 16.3%, 194.2k HPS/31.3k DPS를, 쐐기 고단 상위 5% 7,134표본에서 예언자 99.8%, 공허술사 0.1%, 추천 전문화+영웅 빌드 17.5%, 쐐기돌 +22, 115.4k HPS/26.3k DPS를 표시합니다. Warcraft Priests는 Wowhead 공개 Discord 목록의 Priest 항목으로 공개 진입 경로만 남기고, 로그인/가입이 필요한 원문은 직접 인용하지 않습니다.',
