      '회개는 항상 적에게 쏘는 주문이 아닙니다. 피해 전 준비나 특정 대상 급락에서는 아군 회개가 속죄 적용과 직접 복구를 동시에 해결합니다.',
      '공허의 보호막 발동이 있으면 회개 전에 먼저 쓰는 쪽이 좋습니다. 발동을 들고 있다가 다음 회개로 새 발동을 낭비하는 실수가 자주 납니다.',
      '어둠의 권능: 죽음은 레이드에서 처형 대상이 나올 때마다 의식적으로 봅니다. 단순 딜 버튼이 아니라 속죄 창 안에서 즉시 들어가는 회수 버튼입니다.',
      '쐐기에서 사도 뒤 즉시시전 광휘 2회는 이동 많은 풀에서 매우 강합니다. 사도 버프는 바로 소비하지 않아도 되므로, 다음 광역 피해까지 들고 가는 선택지가 있습니다.',
      '회개 채널은 중간에 끊지 않는 것이 중요합니다. 매크로나 연타 습관 때문에 회개 화살을 덜 쏘면 속죄 회수와 공허의 보호막 발동 판단이 같이 틀어집니다.',
      '마법 무효화, 정화, 대규모 무효화, 신의의 도약은 HPS에 잘 안 보이지만 실제 사망을 줄이는 버튼입니다. 위험 디버프는 힐로 버티기 전에 먼저 지우는 쪽이 맞습니다.',
      '툴팁 API에 남아 있는 주문도 현재 로그 기본 흐름과 직접 연결되지 않으면 전투 흐름 차트에 넣지 않습니다. 이 페이지는 실제 표본과 현재 가이드에서 반복 확인되는 사도/광휘/속죄 축만 기본값으로 둡니다.',
