  summary:
    '신성 사제는 빛의 권능: 평온과 빛의 권능: 신성화를 피해 모양에 맞춰 비우고 다시 채우는 반응형 힐러입니다. 회복의 기원은 전투 전체에 깔리는 보험층이고, 순간 치유, 치유의 기원, 빛의 쇄도, 빛술사, 축도는 다음 권능과 우주의 파장을 더 빨리 여는 실전 도구입니다. 12.0.5 본 패치의 8% 치유량 증가와 2026년 5월 5일 핫픽스의 추가 6% 치유 증가로 숫자는 올라갔지만, 핵심은 여전히 권능 2충전 방치, 회복의 기원 2충전 방치, 후광/절정/천상의 찬가 겹침을 줄이는 것입니다.',
  sourceNote:
    'Wowhead 2026-04-02 운용 가이드는 빛의 권능: 평온, 빛의 권능: 신성화, 회복의 기원을 자주 쓰되 예측 가능한 피해에는 권능을 준비하라고 설명합니다. Icy Veins 2026-05-19 운용 문서는 신성한 환영, 축도, 빛의 쇄도/빛술사, 후광과 절정, 천상의 찬가 배정을 따로 다룹니다. 따라서 이 페이지는 현재 Wowhead/Icy 우선순위와 Wowhead 한국어 툴팁 API로 확인한 실제 신성 사제 버튼만 차트에 남기고, 구버전 또는 타 전문화 버튼은 첫 피해 대응 차트에서 제외합니다. Archon 집계는 2026-05-27 확인 시점 최근 14일 기준 신화 전체 보스 20,608표본에서 집정관 98.8%, 예언자 1.1%, 추천 전문화+영웅 빌드 53.8%, 추천 빌드 174.9k HPS/18.7k DPS를, 쐐기 고단 2,571표본에서 집정관 62.8%, 예언자 37.1%, 추천 전문화+영웅 빌드 8.1%, +19/88.1k HPS/29.0k DPS를 표시합니다. Warcraft Priests는 Wowhead 공개 Discord 목록의 Priest 항목으로 공개 진입 경로만 남기고, 로그인이나 가입이 필요한 원문은 직접 인용하지 않습니다.',
