  summary:
    '암흑 사제는 지속 피해를 깔아 둔 뒤 광기를 어둠의 권능: 광기로 바꾸고, 정신 분열과 공허 계열 쿨다운을 계속 굴려 피해를 회수하는 원거리 딜러입니다. 광역도 광역 버튼을 무작정 누르는 구조가 아니라, 오래 살 대상에게 지속 피해를 깔고 주 대상에 넣은 피해를 영혼의 연결로 번지는 방식입니다. 12.0.5 기준 레이드는 집정관이 92.3%로 주류이고, 쐐기 고단은 공허술사가 82.8%로 주류라 두 콘텐츠의 첫 전투 흐름과 쿨다운 해석을 분리해야 합니다.',
  sourceNote:
    'Blizzard 12.0.5 한국어 업데이트 노트에서는 사제 항목의 직접 변경이 수양과 신성에만 있고, 암흑 직접 변경은 확인되지 않습니다. Wowhead 2026-04-02 암흑 딜사이클 가이드는 흡혈의 손길 유지, 어둠의 권능: 광기 유지와 광기 과잉 방지, 짧은 쿨다운 낭비 방지, 발동 대응을 핵심 원칙으로 둡니다. Icy Veins 2026-05-19 운용/특성 문서는 암흑을 지속 피해 유지와 광기 소비 중심의 생성-소비 구조로 설명하고, 집정관 레이드와 공허술사 쐐기/3타깃 빌드를 분리합니다. Archon 2026-05-27 확인값은 신화 레이드 전체 보스 24,390표본에서 집정관 92.3%, 공허술사 7.6%, 추천 전문화+영웅 빌드 47.0%, 167.3k DPS이고, 쐐기 고단 상위 5% 4,187표본에서는 공허술사 82.8%, 집정관 17.1%, 추천 전문화+영웅 빌드 49.9%, +23/206.9k DPS입니다. Warcraft Priests는 Wowhead 공개 Discord 목록의 사제 직업 Discord 진입 경로만 보조 근거로 남기고, 로그인이나 가입이 필요한 원문은 직접 인용하지 않습니다. 스킬명과 아이콘은 Wowhead 한국어 툴팁 API로 촉수 격돌, 흡혈의 손길, 어둠의 권능: 고통, 공허의 형상, 마력 주입, 어둠의 권능: 광기, 공허 연사, 공허의 격류, 공허의 폭발, 후광, 정신 분열, 어둠의 권능: 죽음, 정신의 채찍을 다시 대조했습니다.',
