  summary:
    '회복 드루이드는 피가 빠진 뒤 버튼을 찾는 힐러가 아니라, 피해가 오기 전에 지속 치유를 깔고 그 지속 치유를 큰 피해 시간에 맞춰 확장하는 예측형 힐러입니다. 12.0.5 기준 핵심은 피어나는 생명과 꽃피우기 유지, 피해 10~12초 전 회복 예열, 피해 순간 급속 성장과 신속한 치유, 그리고 평온/영혼 소집/화신: 생명의 나무 배정입니다. 숲 수호자는 별도로 누르는 버튼이 아니라 신속한 치유 또는 급속 성장으로 생성되는 패시브 발동이므로, 차트에서는 숲 수호자 버튼을 찾지 말고 그 발동을 만드는 주문을 봐야 합니다.',
  sourceNote:
    'Wowhead 2026-05-13 특성 문서는 레이드 기본값을 야생추적자로 두고, 숲의 수호자는 더 큰 순간 치유를 만들 수 있는 선택지로 설명합니다. Icy Veins 2026-05-19는 숲 수호자가 패시브로 바뀌어 신속한 치유와 급속 성장으로 발동한다고 정리하고, 번성도 평온에 붙은 지속 치유 연장 구조로 설명합니다. Dreamgrove 공개 컴펜디엄은 피어나는 생명, 신속한 치유, 회복, 재생, 영혼 소집 중심의 회복 드루이드 점검 순서를 제공하고, #resto 채널에서 로그 링크를 기준으로 피드백을 받으라고 안내합니다. Archon은 2026-05-27(KST) 확인 기준 신화 레이드 최근 14일 상위 50% 41,932표본에서 야생추적자 98.0%, 숲의 수호자 1.9%, 추천 특성+영웅 특성 21.9%, 189.2k HPS/6.6k DPS를, 쐐기 +7 이상 최근 14일 전체 147,884표본에서 야생추적자 81.6%, 숲의 수호자 18.3%, 추천 특성+영웅 특성 20.3%, 쐐기돌 +22, 88.5k HPS/15.5k DPS를, 고단 상위 5% 7,617표본에서 야생추적자 93.8%, 숲의 수호자 6.1%, 추천 특성+영웅 특성 38.9%, 쐐기돌 +22, 104.8k HPS/17.6k DPS를 표시합니다. Dreamgrove는 공개 자료와 Discord 진입 경로만 보조 근거로 쓰며, 로그인/가입 뒤의 대화 원문은 직접 인용하지 않습니다.',
  playstyle: [
    {
      label: '핵심 요약',
      text: '피해가 오기 전에 회복을 넓게 깔고, 피어나는 생명과 꽃피우기를 유지하며, 피해가 들어오는 순간 급속 성장과 신속한 치유, 평온 또는 영혼 소집으로 예열된 지속 치유를 실제 회복량으로 바꿉니다.',
    },
    {
      label: '레이드 운용',
      text: '레이드는 피해 10~12초 전부터 회복을 10개 이상 깔아 풍요를 쌓고, 꽃피우기 위치와 피어나는 생명을 고정한 뒤, 평온/영혼 소집/화신: 생명의 나무를 배정된 피해 타이머에 맞춥니다. 화신을 쓰는 빌드라면 회복을 뿌리기 전에 먼저 켜야 마나 절감과 강화 효과를 제대로 받습니다.',
    },
    {
      label: '쐐기 운용',
      text: '쐐기는 파티 5명의 피해 형태를 읽는 게임입니다. 피어나는 생명, 꽃피우기, 회복을 기본으로 깔고, 급속 성장과 신속한 치유는 실제 피해가 있는 순간에 맞춰 효율을 봅니다.',
    },
    {
      label: '현재 메타',
      text: 'Wowhead와 Archon 기준 레이드는 야생추적자가 압도적 기본값이고, 쐐기 +7 이상 전체 표본도 야생추적자가 우세합니다. 고단 상위 5%로 좁히면 야생추적자 비율이 더 올라가므로 기본 해석은 야생추적자로 둡니다. 숲의 수호자는 쐐기 전체 표본에서 더 많이 보이며, 신속한 치유/급속 성장, 숲 수호자, 숲의 조화, 세나리우스의 인도가 한 덩어리로 움직여 순간 치유 창을 크게 만들 수 있으므로 별도 분기로 다룹니다.',
    },
  ],
  tips: [
    '숲 수호자는 누르는 버튼이 아닙니다. 신속한 치유 또는 급속 성장으로 나무정령이 자동 생성되고, 이 발동이 숲의 조화나 숲의 수호자 분기 가치와 이어집니다.',
    '번성은 별도 액티브가 아닙니다. 현재 툴팁 기준 평온이 1초마다 자신의 지속 치유 효과 지속시간을 늘리는 특성입니다.',
    '숲의 수호자 빌드에서는 신속한 치유와 급속 성장을 늦게 누르는 것이 곧 숲 수호자 손실입니다. 큰 피해 전에는 둘을 아껴 둘 수 있지만, 평소에는 쿨이 놀지 않는지부터 봅니다.',
    '영혼 소집은 시전자 형태에서 쓰면 회복, 급속 성장, 신속한 치유 쪽으로 기울고, 다른 변신 상태에서는 주문 풀이 달라집니다. 치유가 목적이면 폼부터 확인합니다.',
    '녹음의 유혹이 뜬 신속한 치유는 단순 즉시 치유가 아니라 드리아드의 평온/재생을 여는 버튼입니다. 버프를 오래 들고 있지 말고 실제 피해 구간에 소비합니다.',
    '마나가 부족하면 재생을 줄이기 전에 피해 전 회복 예열이 실제 피해 타이머와 맞았는지부터 봅니다. 회복을 엉뚱한 시간에 많이 깔면 풍요도, 재생 효율도 같이 무너집니다.',
    '꽃피우기는 바닥 장판이 아니라 파티가 실제로 서 있을 위치를 지정하는 주문입니다. 쐐기에서는 탱커가 모는 위치, 레이드에서는 지정 뭉침 위치를 먼저 봅니다.',
    '신속한 치유 뒤에는 다음 주문이 무엇인지까지 묶어서 생각합니다. 숲의 영혼, 대드루이드의 힘, 신록 주입, 숲 수호자 발동이 모두 여기에서 갈라집니다.',
    '평온은 위기 때 급하게 누르는 버튼이 아니라 지속 치유가 이미 깔린 상태에서 가장 강해지는 배정 쿨다운입니다. 공대 피해가 오기 전에 준비가 끝나 있어야 합니다.',
    '영혼 소집은 회복 드루이드에게 짧고 강한 랜덤성 치유 창입니다. 치유가 필요하면 시전자 형태, 딜 기여가 필요하면 표범 변신 여부를 분리해서 판단합니다.',
    '쐐기에서는 자연의 치유력, 무쇠껍질, 쇄도의 포효가 HPS보다 큰 가치를 만들 때가 많습니다. 차단 실패나 이동 실패를 힐량으로만 복구하려고 하면 마나가 먼저 무너집니다.',
    '12.0.5 쐐기 딜 기여는 표범 변신만 고집하지 않습니다. 안전한 거리에서 태양섬광, 달빛섬광, 천벌을 굴리는 쪽이 더 안정적인 풀도 많습니다.',
  ],
