    '광역에서는 표창 폭풍과 검은 화약을 쓰지만, 우선 처치 대상이 있으면 은밀한 기술과 절개 타이밍을 같이 봅니다.',
    '책략가는 최후의 일격과 무형검 보상을 놓치지 않는지가 핵심입니다. 죽음추적자는 죽음추적자의 징표가 엉뚱한 대상에 붙지 않아야 합니다.',
